// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Psikoloji temel kavramları (lise psikoloji dersi) (zor).
const ozSocialscience2Zor = <(String, String, List<String>, String)>[
  ('İşlevselciliğin psikolojiye kazandırdığı uygulamalı alanlardan biri aşağıdakilerden hangisidir?', 'Eğitim psikolojisi', ['Psikanalitik terapi', 'Gestalt algı araştırmaları', 'Fizyolojik iç gözlem'], 'İşlevselcilerin uyum ve öğrenmeye verdiği önem, John Dewey gibi isimler aracılığıyla eğitim psikolojisinin gelişmesine katkı sağlamıştır.'),
  ('Aşağıdakilerden hangisi işlevselciliğin yapısalcılıktan farklı olarak araştırma kapsamına aldığı konulardan biridir?', 'Çocuklar ve hayvanlar üzerindeki çalışmalar', ['Yalnız eğitimli yetişkinlerin iç gözlemi', 'Duyumların en küçük öğelerine ayrılarak sınıflandırılması', 'Tepki süresinin hiç ölçülmemesi'], 'İşlevselciler iç gözlemle sınırlı kalmayıp çocuk, hayvan ve bireysel farklılıklar üzerine de çalışarak psikolojinin kapsamını genişletmiştir.'),
  ('Freud\'la çalıştıktan sonra ondan ayrılıp kolektif bilinçdışı kavramını geliştiren psikolog kimdir?', 'Carl Gustav Jung', ['Alfred Adler', 'Karen Danielsen Horney', 'Erik Erikson'], 'Jung, bireysel bilinçdışının yanı sıra insanlığın ortak arketiplerini içeren kolektif bilinçdışı kavramını ortaya atmıştır.'),
  ('Max Wertheimer\'ın Gestalt psikolojisini başlatan çalışması hangi olguyla ilgilidir?', 'Ardışık yanıp sönen ışıklarda görülen görünür hareket', ['Köpeklerde zil sesiyle salya salgılanmasının öğrenilmesi', 'Bebeklerde emme refleksi', 'Kedilerin kafesten kaçması'], 'Wertheimer, belli aralıklarla yanıp sönen iki ışığın tek bir hareket eden ışık gibi algılanmasını (phi olgusu) inceleyerek Gestalt yaklaşımını başlatmıştır.'),
  ('Bir müzik parçası farklı bir tonda çalındığında bütün notalar değiştiği hâlde aynı melodi olarak tanınır. Bu durum hangi yaklaşımın görüşünü destekler?', 'Gestalt yaklaşımı', ['Yapısalcılık', 'Davranışçılık', 'Biyolojik yaklaşım'], 'Notaların tümü değişse de aralarındaki ilişki korunduğu için melodi aynı bütün olarak algılanır; bu, bütünün parçalardan farklı olduğu ilkesini destekler.'),
  ('Rogers\'a göre kişinin \'olmak istediği benlik\' ile \'gerçekte olduğuna inandığı benlik\' arasındaki büyük fark neye yol açar?', 'Uyumsuzluk ve kaygıya', ['Kendini gerçekleştirmeye', 'Güçlü bir süper egoya', 'Kalıcı bir mutluluğa'], 'Rogers, ideal benlik ile gerçek benlik arasındaki uyumsuzluk arttıkça kişinin kaygı ve psikolojik sıkıntı yaşadığını ileri sürmüştür.'),
  ('Bilişsel yaklaşımın 1950\'ler ve 1960\'larda yükselişini hızlandıran gelişme hangisidir?', 'Bilgisayar bilimi ve bilgi işleme kuramlarının gelişmesi', ['Psikanalizin tıpta yaygınlaşması', 'İç gözlemin yeniden kabul görmesi', 'Darwin\'in evrim kuramının ilk kez yayımlanıp geniş kabul görmesi'], 'Bilgisayar bilimindeki ilerlemeler zihinsel süreçleri bilgi işleme kavramlarıyla modellemeyi mümkün kılmış ve \'bilişsel devrim\'e katkı sağlamıştır.'),
  ('Davranışı yalnızca nörotransmitterler ve genlerle açıklayan bir görüşe en çok hangi gerekçeyle itiraz edilebilir?', 'Çevresel ve kültürel etkileri göz ardı ederek davranışı indirgemesi', ['Beyin araştırmalarının bulgularını bütünüyle reddetmesi ve önemsememesi', 'Deneysel yöntemi hiç kullanmayıp yalnız iç gözleme dayanması', 'Hormonların etkisini yok sayması'], 'Biyolojik yaklaşım karmaşık davranışları yalnızca kimyasal ve genetik düzeye indirgediği için indirgemecilikle eleştirilir.'),
  ('Aynı saldırgan davranışı açıklamak için bir psikolog \'beyindeki serotonin düzeyi\', diğeri \'şiddet içeren modellerin gözlenmesi\' açıklamasını yapıyor. Bu iki psikoloğun yaklaşımları sırasıyla hangisidir?', 'Biyolojik ve sosyal öğrenme', ['Bilişsel ve psikanalitik', 'Hümanistik ve biyolojik yaklaşımlar', 'Gestalt ve davranışçı'], 'Nörotransmitter düzeyine dayalı açıklama biyolojik, model gözleyerek öğrenmeye dayalı açıklama ise sosyal öğrenme yaklaşımına aittir.'),
  ('Günümüz psikolojisinde \'eklektik\' yaklaşım ne anlama gelir?', 'Bir olguyu açıklamak için farklı kuramlardan uygun olanların birlikte kullanılması', ['Yalnızca tek bir kuramın kesin doğru kabul edilmesi', 'Bilimsel yöntemin tümüyle bırakılması', 'Sadece biyolojik açıklamaların geçerli sayılması'], 'Eklektik tutum, tek bir kuramın her şeyi açıklayamayacağı düşüncesiyle farklı yaklaşımların güçlü yönlerini bir araya getirir.'),
  ('Temel araştırma ile uygulamalı araştırma arasındaki fark hangi seçenekte doğru verilmiştir?', 'Temel araştırma bilgi üretmeyi, uygulamalı araştırma sorun çözmeyi amaçlar.', ['Temel araştırma yalnız hayvanlarla, uygulamalı yalnız insanlarla yapılır.', 'Uygulamalı araştırmada hiçbir kuram kullanılmaz.', 'Temel araştırma sadece anketle yapılır.'], 'Temel araştırmalar bilimsel bilgiyi genişletmeyi, uygulamalı araştırmalar ise gerçek yaşamdaki sorunlara çözüm üretmeyi hedefler.'),
  ('\'Müzik dinlemek el becerisini artırır mı?\' sorusunu inceleyen bir deneyde katılımcıların önceki el becerisi düzeyleri gruplar arasında dengelenmemiştir. Bu durum hangi riski doğurur?', 'Sonucun müziğe değil başka bir değişkene bağlı olabilmesi', ['Bağımlı değişkenin hiç ölçülememesi', 'Deneyin doğal gözleme dönüşmesi', 'Kontrol grubunun gereksiz hâle gelmesi'], 'Gruplar başlangıçta farklıysa sonuçtaki fark karıştırıcı bir değişkenden kaynaklanabilir ve neden-sonuç çıkarımı zayıflar.'),
  ('Bir araştırmacı \'stres\' kavramını \'katılımcının dakikadaki kalp atım sayısı\' olarak ölçülebilir biçimde tanımlıyor. Bu işleme ne ad verilir?', 'İşlevsel (operasyonel) tanımlama', ['Hipotez reddi', 'Örneklemden evrene genelleme', 'İç gözlem'], 'Soyut bir kavramın ölçülebilir işlemlerle tanımlanmasına işlevsel tanım denir; bu, araştırmanın tekrarlanabilmesini sağlar.'),
  ('Bir araştırmada dondurma satışları ile boğulma vakaları arasında pozitif korelasyon bulunmuştur. Bu bulgudan çıkarılabilecek en doğru sonuç hangisidir?', 'İkisini de artıran sıcak hava gibi üçüncü bir değişken olabilir.', ['Dondurma yemek boğulmaya neden olur.', 'Boğulma vakaları dondurma satışını artırır.', 'İki değişken arasında ilişki yoktur.'], 'Korelasyon nedensellik göstermez; yaz aylarındaki sıcaklık hem dondurma tüketimini hem de yüzmeyi dolayısıyla boğulmaları artırabilir.'),
  ('Gözlenen kişilerin izlendiklerini bildikleri için davranışlarını değiştirmesi hangi kavramla adlandırılır?', 'Hawthorne etkisi', ['Plasebo etkisi', 'Hale etkisi', 'Pygmalion (beklenti) etkisi'], 'İnsanların gözlendiklerini bildiklerinde farklı davranması, ilk kez bir fabrikadaki çalışmalarda fark edildiği için Hawthorne etkisi olarak anılır.'),
  ('Psikolojide aldatma içeren deneylere ilişkin genel etik yaklaşım hangisidir?', 'Başka yolla bilgi elde edilemiyorsa ve zarar riski düşükse, sonunda açıklanmak koşuluyla kabul edilebilir.', ['Her durumda kesinlikle yasaktır ve hiçbir gerekçeyle kabul edilemez.', 'Aldatma yapıldıysa bu durum katılımcıya hiçbir zaman açıklanmamalıdır.', 'Yalnızca çocuklarla yapılan çalışmalarda serbesttir.'], 'Etik kurallar aldatmayı zorunlu durumlarla sınırlar, ciddi zarar riskini yasaklar ve deney sonunda bilgilendirmeyi şart koşar.'),
  ('Ya hep ya hiç ilkesine göre güçlü bir uyarıcının zayıf bir uyarıcıdan farklı algılanması nasıl sağlanır?', 'Nöronların daha sık ateşlenmesi ve daha çok nöronun devreye girmesiyle', ['Tek bir sinir uyarısının daha güçlü olmasıyla', 'Uyarının akson boyunca yön değiştirmesiyle', 'Miyelin kılıfın her uyarıda kalınlaşmasıyla'], 'Tek bir aksiyon potansiyelinin şiddeti sabittir; şiddet bilgisi ateşlenme sıklığı ve etkinleşen nöron sayısıyla kodlanır.'),
  ('Kas kasılmasında ve bellek süreçlerinde görev alan, Alzheimer hastalığında azaldığı bilinen nörotransmitter hangisidir?', 'Asetilkolin', ['Serotonin', 'Glutamat', 'Endorfin'], 'Asetilkolin motor nöronlarla kaslar arasında iletimi sağlar; ayrıca öğrenme ve bellekle ilişkilidir ve Alzheimer\'da üretimi azalır.'),
  ('Merkezi sinir sistemindeki başlıca ketleyici (yavaşlatıcı) nörotransmitter hangisidir?', 'GABA', ['Glutamat', 'Dopamin', 'Noradrenalin'], 'GABA nöronların ateşlenme olasılığını azaltan başlıca ketleyici nörotransmitterdir; kaygıyı azaltan bazı ilaçlar GABA\'nın etkisini artırır.'),
  ('Bir nörotransmitterin sinaptik boşlukta işi bittikten sonra salgılayan nöron tarafından geri alınmasına ne ad verilir?', 'Geri alım', ['Miyelinleşme', 'Depolarizasyon', 'Ateşlenme'], 'Geri alım, nörotransmitterin akson ucuna geri çekilmesidir; bazı antidepresanlar serotoninin geri alımını engelleyerek etkisini uzatır.'),
  ('Wernicke alanında hasar olan bir hastada en belirgin hangi durum gözlenir?', 'Akıcı ama anlamsız konuşma ve söyleneni anlayamama', ['Konuşmanın tümüyle durması ve sesin kısılması', 'Görme alanının yarısının kaybedilmesi', 'Denge kaybı ve titrek yürüyüş'], 'Wernicke alanı dili anlamada görevlidir; hasarında kişi akıcı konuşur ama sözleri anlamsızdır ve başkalarını anlamakta zorlanır.'),
  ('Uyku-uyanıklık döngüsü ve dikkat düzeyinin düzenlenmesinde rol oynayan, beyin sapı boyunca uzanan ağ yapısı hangisidir?', 'Retiküler formasyon', ['Wernicke alanı', 'Korpus kallozum', 'Bazal ganglion'], 'Retiküler aktive edici sistem uyarılmışlık ve uyanıklık düzeyini düzenler; hasarı bilinç kaybına yol açabilir.'),
  ('Uzun süreli stres altında salgılanan ve sürekli yüksek kalması bağışıklık sistemini zayıflatabilen hormon hangisidir?', 'Kortizol', ['İnsülin', 'Melatonin', 'Büyüme hormonu'], 'Kortizol böbrek üstü kabuğundan salgılanan stres hormonudur; kronik yüksekliği bağışıklığı baskılar.'),
  ('Weber yasasına göre 100 gramlık bir ağırlığa 2 gram eklendiğinde fark ancak sezilebiliyorsa, 500 gramlık bir ağırlıkta farkın sezilmesi için en az kaç gram eklemek gerekir?', '10 gram', ['2 gram', '5 gram', '25 gram'], 'Weber yasasına göre fark eşiği uyarıcının şiddetiyle orantılıdır. Oran 2/100 = 0,02 olduğundan 500 × 0,02 = 10 gram gerekir.'),
  ('Sinyal saptama kuramına göre bir radar operatörünün ekrandaki zayıf bir sinyali fark edip etmemesi aşağıdakilerden hangisine bağlı değildir?', 'Ekranın bulunduğu odanın duvar renginin adı', ['Operatörün yorgunluk düzeyi', 'Sinyali kaçırmanın doğuracağı sonuçlar', 'Operatörün sinyal beklentisi'], 'Sinyal saptama kuramı, uyarıcı şiddetinin yanı sıra kişinin beklenti, güdü ve yorgunluk gibi psikolojik etkenlerinin de algılamayı etkilediğini söyler.'),
  ('Kırmızı bir kareye bir süre baktıktan sonra beyaz bir duvara bakan kişi, duvarda yeşil bir kare görüyor. Bu olguyu en iyi açıklayan kuram hangisidir?', 'Karşıt süreç kuramı', ['Üç renk kuramı', 'Kapı kontrol kuramı', 'Yer kuramı'], 'Karşıt süreç kuramına göre renkler kırmızı-yeşil, mavi-sarı gibi karşıt çiftlerle işlenir; birinin yorulması karşıtının ard görüntüsüne yol açar.'),
  ('Koku bilgisinin diğer duyulardan farklı olarak hangi özelliği vardır?', 'Talamusa uğramadan doğrudan beynin koku bölgesine ulaşması', ['Beyne hiç ulaşmadan omurilikte işlenmesi ve orada kalması', 'Yalnızca sol yarım kürede işlenip sağda hiç işlenmemesi', 'Retinadaki çubuk hücreler aracılığıyla algılanması'], 'Koku duyusu talamusta aktarılmadan doğrudan koku soğancığına ve limbik sisteme ulaşır; bu nedenle kokular duygu ve anılarla güçlü bağ kurar.'),
  ('Ağrının algılanmasında omurilikteki bir \'kapının\' sinyalleri geçirdiğini ya da engellediğini öne süren kuram hangisidir?', 'Kapı kontrol kuramı', ['Karşıt süreç kuramı', 'Üç renk kuramı', 'Sinyal saptama kuramı'], 'Melzack ve Wall\'un kapı kontrol kuramına göre omurilikteki mekanizma ağrı sinyallerinin beyne ulaşmasını artırabilir ya da azaltabilir; çarpılan yeri ovmak bu yüzden ağrıyı hafifletir.'),
  ('Yakındaki bir nesneye bakarken gözlerin içe doğru dönmesi ve bu kas gerginliğinin uzaklık bilgisi vermesi hangi ipucudur?', 'Yakınsama', ['Doku eğimi', 'Doğrusal perspektif', 'Göreli parlaklık'], 'Yakınsama iki göz ipucudur; nesne yaklaştıkça gözler daha çok içe döner ve beyin bu kas bilgisinden uzaklığı kestirir.'),
  ('Aynı uzunluktaki iki çizgiden ucunda dışa açık oklar olanın daha uzun algılandığı yanılsama hangisidir?', 'Müller-Lyer yanılsaması', ['Ay yanılsaması', 'Ponzo (demiryolu) yanılsaması', 'Phi olgusu'], 'Müller-Lyer yanılsamasında okların yönü çizgilerin uzunluk algısını değiştirir; ölçüldüğünde çizgiler eşittir.'),
  ('Ufka yakınken Ay\'ın tepedeyken olduğundan daha büyük görünmesine ne denir ve bu ne tür bir olgudur?', 'Ay yanılsaması; algısal bir yanılgıdır', ['Ay yanılsaması; Ay\'ın gerçekten yaklaşmasıdır', 'Phi olgusu; gerçek bir harekettir', 'Duyusal uyum; retina yorgunluğudur'], 'Ay\'ın ufukta büyük görünmesi fiziksel bir büyüme değil, beynin uzaklık yorumundan kaynaklanan bir algı yanılsamasıdır.'),
  ('Uykuda yürüme ve gece terörü gibi durumlar en çok hangi uyku evresinde ortaya çıkar?', 'Derin NREM uykusu', ['REM uykusu', 'Uykuya dalma öncesi uyanıklık', 'Sabaha karşı hafif uyku'], 'Uyurgezerlik ve gece terörü REM\'de değil, kasların hareket edebildiği derin NREM evresinde görülür.'),
  ('Birkaç gece boyunca REM uykusundan yoksun bırakılan kişilerin, serbest bırakıldıklarında normalden daha fazla REM uykusuna girmesine ne ad verilir?', 'REM geri tepmesi', ['Sirkadiyen kayma', 'Narkolepsi', 'Uyku apnesi'], 'REM\'den yoksun kalan beyin ilk fırsatta bu evreyi telafi eder; bu durum REM\'in önemli bir ihtiyaç olduğunu düşündürür.'),
  ('Rüyaları beyin sapından gelen rastgele sinirsel uyarıların beyin kabuğunca anlamlandırılma çabası olarak açıklayan kuram hangisidir?', 'Etkinleşme-sentez kuramı', ['Bilinçdışı istek doyumu kuramı', 'Bilgi işleme kuramı', 'Kapı kontrol kuramı'], 'Hobson ve McCarley\'nin etkinleşme-sentez kuramı, rüyaların REM sırasında rastgele sinirsel etkinliğe anlam yüklenmesinden doğduğunu öne sürer.'),
  ('Klasik koşullanmanın en etkili olması için koşullu uyarıcı ile koşulsuz uyarıcı nasıl sunulmalıdır?', 'Koşullu uyarıcı, koşulsuz uyarıcıdan hemen önce verilmelidir.', ['Koşulsuz uyarıcı, koşullu uyarıcıdan birkaç saat önce verilmelidir.', 'İki uyarıcı arasında en az bir gün beklenmelidir.', 'Koşullu uyarıcı yalnızca koşulsuz uyarıcıdan sonra verilmelidir.'], 'Koşullu uyarıcı koşulsuz uyarıcıdan kısa bir süre önce sunulduğunda bir işaret işlevi görür ve öğrenme en hızlı gerçekleşir.'),
  ('Bir kişi bir lokantada balık yedikten saatler sonra mide virüsü yüzünden hastalanıyor ve o günden sonra balık kokusundan bile tiksiniyor. Bu olgunun klasik koşullanmadaki özel önemi nedir?', 'Tek bir eşleştirmeyle ve uzun bir zaman aralığına rağmen öğrenmenin gerçekleşebilmesi', ['Bu tür öğrenmenin yalnızca hayvanlarda ortaya çıkması ve insanda görülmemesi', 'Öğrenmenin ancak yüzlerce tekrardan sonra oluşabilmesi', 'Hastalanmanın her zaman olumlu pekiştireç işlevi görmesi'], 'Garcia\'nın tat tiksintisi çalışmaları, biyolojik olarak hazır olunan bazı öğrenmelerin tek denemede ve saatlerce gecikmeye karşın oluşabileceğini göstermiştir.'),
  ('Klasik koşullanma ile edimsel koşullanma arasındaki temel fark hangisidir?', 'Klasikte istemsiz tepkiler uyarıcılarla, edimselde istemli davranışlar sonuçlarıyla ilişkilendirilir.', ['Klasikte yalnızca ödül, edimselde yalnızca ceza kullanılır.', 'Klasik koşullanma yalnız insanlarda, edimsel koşullanma yalnız hayvanlarda görülür.', 'Edimselde uyarıcılar eşleştirilir, klasikte davranışın sonucu belirleyicidir.'], 'Klasik koşullanma refleksif tepkilerin yeni uyarıcılara bağlanmasıdır; edimsel koşullanmada ise organizmanın gönüllü davranışı ardından gelen sonuçla biçimlenir.'),
  ('Bir öğretmenin habersiz kısa sınavları rastgele günlerde yapması öğrencilerin hangi tarifeyle pekiştirilmesine benzer ve nasıl bir çalışma davranışı doğurur?', 'Değişken aralıklı; düzenli ve sürekli çalışma', ['Sabit aralıklı; sınav öncesi yığılmalı çalışma', 'Sabit oranlı; hızlı ama kesintili çalışma', 'Sürekli pekiştirme; çok hızlı sönme'], 'Sınavların zamanı önceden bilinmediğinden öğrenciler her an hazırlıklı olmaya çalışır; değişken aralıklı tarife istikrarlı tepki oranı üretir.'),
  ('Sabit aralıklı pekiştirme tarifesinde tepki örüntüsünün tipik özelliği nedir?', 'Pekiştireç zamanı yaklaştıkça tepkilerin artması, sonrasında düşmesi', ['Tepkilerin her zaman aynı ve kesintisiz hızda sürmesi', 'Pekiştireç verildikten hemen sonra tepkilerin en üst düzeye çıkması', 'Tepkilerin bu tarifede hiçbir zaman sönmemesi'], 'Bu tarifede canlı pekiştirecin ne zaman geleceğini öğrenir; tepkiler pekiştireçten hemen sonra azalır, süre dolmaya yaklaşırken artar.'),
  ('Sürekli pekiştirmeyle öğrenilen bir davranışın aralıklı pekiştirmeyle öğrenilene göre daha çabuk sönmesinin nedeni nedir?', 'Pekiştirecin kesildiği daha kolay fark edildiği için', ['Sürekli pekiştirmede davranışın hiç öğrenilmemiş olması nedeniyle', 'Aralıklı pekiştirmenin davranışı hiç etkilememesi nedeniyle', 'Sürekli pekiştirmenin yalnızca ceza içermesi nedeniyle'], 'Her tepkisi ödüllendirilen canlı ödülün kesildiğini hemen anlar; aralıklı pekiştirmede ise ödülsüz denemeler zaten olağan olduğundan sönme gecikir.'),
  ('Öğrenme ile performans arasındaki ayrım için en iyi örnek hangisidir?', 'Bir çocuğun gördüğü davranışı ancak ödül vaat edildiğinde sergilemesi', ['Bir köpeğin zil sesine salya salgılaması', 'Bir öğrencinin her gün aynı saatte uyanması', 'Bir bebeğin doğuştan emme refleksi göstermesi'], 'Bandura\'nın çalışmalarında da görüldüğü gibi, öğrenilen bir davranış hemen gösterilmeyebilir; uygun güdü ortaya çıkınca performansa dönüşür.'),
  ('Bilginin anlamı üzerinde düşünülerek ve var olan bilgilerle ilişkilendirilerek işlenmesinin hatırlamayı artırdığını öne süren yaklaşım hangisidir?', 'İşlemleme düzeyleri yaklaşımı', ['Bozulma (iz silinmesi) kuramı', 'Çok depolu bellek modeli', 'Ya hep ya hiç ilkesi'], 'Craik ve Lockhart\'a göre bilgi ne kadar derin, yani anlamsal düzeyde işlenirse o kadar iyi hatırlanır.'),
  ('Bir deneyde bir gruba sözcüklerin harf sayısı, diğer gruba sözcüklerin anlamı soruluyor. Sonradan habersiz yapılan bellek testinde hangi sonuç beklenir?', 'Anlamı soran grubun sözcükleri daha iyi hatırlaması', ['Harf sayısını soran grubun daha iyi hatırlaması', 'İki grubun hiçbir sözcüğü hatırlayamaması', 'İki grubun tam olarak aynı sayıda sözcük hatırlaması'], 'Anlam üzerine düşünmek derin işlemlemedir; yüzeysel özelliklere odaklanmaya göre daha kalıcı bellek izi bırakır.'),
  ('Çocukken köpek ısırmış olan bir yetişkinin olayı hatırlamadığı hâlde köpek görünce huzursuz olması hangi bellek türüyle açıklanır?', 'Örtük bellek', ['Anısal bellek', 'Anlamsal bellek', 'Çalışma belleği'], 'Örtük bellekte bilgi bilinçli olarak hatırlanmadan davranışı etkiler; koşullanmış duygusal tepkiler buna örnektir.'),
  ('Bir kişinin önceden okuduğu bir sözcüğü fark etmeden sonraki bir testte daha hızlı tanıması hangi olguya örnektir?', 'Hazırlama (ön uyarım) etkisi', ['Ket vurma etkisi', 'Bilinçli ve istemli geri çağırma', 'Bozulma etkisi'], 'Hazırlama etkisinde daha önce karşılaşılan bir uyarıcı, kişi farkında olmasa da sonraki işlemleri kolaylaştırır; örtük belleğin bir göstergesidir.'),
  ('Bir öğrenci sınavın sabahı çalışmak yerine akşam ders çalışıp uyuyor ve daha iyi hatırlıyor. Bu durum hangi kuramla en iyi açıklanır?', 'Ket vurma kuramı', ['Bozulma kuramı', 'Güdülenmiş unutma', 'Sinyal saptama kuramı'], 'Uyku sırasında yeni öğrenmeler araya girmediğinden ket vurma azalır ve öğrenilen bilgi daha iyi korunur.'),
  ('Her gün kullandığımız bir madeni paranın üzerindeki ayrıntıları doğru çizememenin en olası nedeni nedir?', 'Bu ayrıntıların hiç kodlanmamış olması', ['Bilginin ileriye ket vurmayla silinmesi', 'Anının bilinçdışına bastırılması', 'Ayrıntıların uzun süreli bellekte çürümesi'], 'Paranın ayrıntılarına hiç dikkat etmediğimiz için bu bilgiler belleğe hiç aktarılmamıştır; bu kodlama başarısızlığıdır.'),
  ('Loftus\'un deneyinde araba kazası videosunu izleyenlere \'arabalar çarpıştığında\' yerine \'arabalar birbirine bindirdiğinde\' diye sorulduğunda, katılımcılar hızı nasıl tahmin etmiştir?', 'Daha yüksek', ['Daha düşük', 'Tam olarak aynı', 'Hiç tahmin edememiştir'], 'Sorudaki fiilin şiddeti arttıkça katılımcılar hızı daha yüksek tahmin etmiş, bazıları olmayan kırık camları bile hatırlamıştır.'),
  ('Görgü tanıklığının mahkemelerde dikkatle değerlendirilmesi gerektiğini savunanların en güçlü psikolojik gerekçesi hangisidir?', 'Belleğin yeniden yapılandırıcı olması ve sonraki bilgilerle değişebilmesi', ['Tanıkların her zaman bilinçli olarak yalan söylemesi', 'Uzun süreli belleğin yalnızca birkaç dakika sürmesi ve sonra tümüyle silinmesi', 'İnsanların gördükleri yüzleri asla tanıyamaması'], 'Bellek bir kayıt cihazı gibi çalışmaz; hatırlama sırasında anılar beklenti ve sonradan gelen bilgilerle yeniden kurulabilir.'),
  ('Bir dalgıç grubunun su altında öğrendiği sözcükleri su altında, karada öğrendiklerini ise karada daha iyi hatırladığı bulunmuştur. Bu bulgu hangi ilkeyle açıklanır?', 'Bağlama bağlı bellek', ['Duruma bağımsız kodlama ilkesi', 'Dizi konum etkisi', 'Bozulma kuramının ilkesi'], 'Öğrenme sırasındaki ortamın ipuçları geri getirmeye yardım eder; öğrenme ve hatırlama ortamları benzer olduğunda hatırlama artar.'),
  ('Bilgiyi ezberlemek yerine kendi kendini sınayarak hatırlamaya çalışmanın öğrenmeyi güçlendirmesine ne ad verilir?', 'Sınama etkisi', ['Sönme etkisi', 'Hale etkisi', 'Plasebo etkisi'], 'Bilgiyi bellekten çağırma alıştırması, yalnızca yeniden okumaya göre daha kalıcı öğrenme sağlar.'),
  ('Öğrenmenin tam olarak sağlandığı noktadan sonra da bir süre tekrar yapılmasına ne ad verilir ve ne işe yarar?', 'Aşırı öğrenme; bilginin daha uzun süre korunmasını sağlar', ['Aşırı öğrenme; bilginin daha çabuk unutulmasına yol açar', 'Ket vurma; yeni bilginin öğrenilmesini kolaylaştırır', 'Sönme; öğrenilen davranışı tümüyle ortadan kaldırır'], 'Bilgi bir kez hatırlanır hâle geldikten sonra da tekrar etmek bellek izini güçlendirir ve unutmayı geciktirir.'),
  ('Bir kişinin uçak kazalarını haberlerde sık gördüğü için uçak yolculuğunu araba yolculuğundan daha tehlikeli sanması hangi düşünme hatasıdır?', 'Hazır bulunuşluk (akla kolay gelme) sezgisi', ['Temsil edicilik (benzerliğe dayalı) sezgisi', 'Doğrulama yanlılığı', 'İşlevsel saplantı'], 'Akla kolay gelen örnekler olayın gerçekte olduğundan daha sık yaşandığı izlenimini doğurur.'),
  ('Aynı bilgi \'Ameliyat edilenlerin %90\'ı yaşıyor\' ve \'Ameliyat edilenlerin %10\'u ölüyor\' biçiminde sunulduğunda insanların ilk ifadeyle ameliyatı daha çok kabul etmesi hangi olguya örnektir?', 'Çerçeveleme etkisi', ['İşlevsel saplantı', 'Dizi konum etkisi', 'Kendini doğrulayan kehanet'], 'Kararlar yalnızca bilginin içeriğinden değil sunuluş biçiminden de etkilenir; buna çerçeveleme etkisi denir.'),
  ('İngilizce öğrenen bir çocuğun \'went\' yerine kuralı fazla uygulayarak \'goed\' demesi hangi dil olgusuna örnektir?', 'Aşırı düzenleme', ['Telgraf konuşma', 'Babıldama dönemi', 'Dil için kritik dönemin kaybedilmesi'], 'Çocuk geçmiş zaman kuralını öğrenmiş ama düzensiz fiillere de uygulamıştır; bu, dili taklitle değil kural çıkararak öğrendiğini gösterir.'),
  ('Konuştuğumuz dilin düşünme biçimimizi ve dünyayı algılayışımızı etkilediğini öne süren görüş hangisidir?', 'Dilsel görelilik görüşü', ['Dil edinim düzeneği görüşü', 'Etki yasası ilkesi', 'Ya hep ya hiç ilkesi'], 'Sapir ve Whorf\'a dayandırılan dilsel görelilik görüşü, dilin düşünceyi biçimlendirdiğini öne sürer; güçlü biçimi tartışmalıdır, zayıf biçimi ise kısmen desteklenir.'),
  ('Zihinsel yaşın takvim yaşına bölünmesine dayanan eski IQ hesaplama yönteminin yetişkinlerde kullanışsız kalmasının temel nedeni nedir?', 'Zihinsel yaşın yetişkinlikte takvim yaşı gibi düzenli artmaması', ['Yetişkinlerin zekâ testlerine hiç katılmak istememesi', 'Yetişkinlerde takvim yaşının tam olarak hesaplanamaması', 'Yetişkinlerde zekânın her yıl iki katına çıkması ve ölçülememesi'], 'Zihinsel yaş belirli bir yaştan sonra artmayı büyük ölçüde durdurduğundan formül yaşlandıkça yapay olarak düşen puanlar verir; bu yüzden sapma IQ\'suna geçilmiştir.'),
  ('Modern zekâ testlerinde puanlar ortalaması 100, standart sapması 15 olan normal dağılıma göre hesaplanır. Buna göre IQ puanı 115 olan bir kişi için ne söylenebilir?', 'Ortalamanın bir standart sapma üzerindedir.', ['Ortalamanın tam olarak iki standart sapma üzerindedir.', 'Ortalamanın bir standart sapma altındadır.', 'Zihinsel yetersizlik sınırının altında kalmaktadır.'], '115 - 100 = 15 olduğundan puan ortalamanın tam bir standart sapma üzerindedir.'),
  ('Cattell\'e göre yaşla birlikte biriken bilgi ve sözcük dağarcığına dayanan zekâ türüne ne ad verilir?', 'Kristalize zekâ', ['Akıcı zekâ', 'Genel zekâ etkeni', 'Duygusal zekâ'], 'Kristalize zekâ deneyim ve eğitimle birikir, yaşlılıkta bile korunabilir; akıcı zekâ ise yeni problemleri hızla çözme becerisidir ve yaşla azalma eğilimindedir.'),
  ('Tek yumurta ikizlerinin zekâ puanlarının, aynı evde büyüyen çift yumurta ikizlerine göre birbirine daha benzer olması neyi gösterir?', 'Kalıtımın zekâ üzerinde etkili olduğunu', ['Çevrenin zekâyı hiç etkilemediğini', 'Zekânın yalnız okul eğitimiyle belirlendiğini', 'İkizlerin zekâ testine hiç girmediğini'], 'Tek yumurta ikizleri genlerin tümünü, çift yumurta ikizleri ise yaklaşık yarısını paylaştığından daha yüksek benzerlik kalıtımın etkisine işaret eder.'),
  ('Bir çocuğun boncukları uzunluklarına göre kısa olandan uzun olana doğru sıralayabilmesi Piaget\'nin hangi kavramına örnektir ve hangi dönemde belirginleşir?', 'Sıralama; somut işlemler dönemi', ['Sıralama; duyusal-motor dönem', 'Nesne sürekliliği; işlem öncesi dönem', 'Animizm; soyut işlemler dönemi'], 'Nesneleri bir özelliğe göre düzenli sıraya koyma becerisi somut işlemler döneminde kazanılır.'),
  ('Piaget\'ye göre çocuğun mevcut şemaları ile yeni yaşantılar arasında uyuşmazlık olduğunda ortaya çıkan ve bilişsel gelişimi harekete geçiren durum nedir?', 'Dengesizlik ve dengeleme ihtiyacı', ['Koşulsuz uyarıcı ile koşulsuz tepkinin eşleşmesi', 'Ket vurma ve bozulma', 'Bastırma ve yansıtma'], 'Yeni bilgi var olan şemalara uymadığında dengesizlik doğar; çocuk özümleme ve uyumsama yoluyla yeniden dengeye ulaşarak gelişir.'),
  ('Piaget\'nin kuramına yöneltilen eleştirilerden biri hangisidir?', 'Çocukların bazı yetenekleri onun öngördüğünden daha erken kazandığının bulunması', ['Çocukların düşünme biçimini hiç incelememiş olması', 'Gelişimin evrelerden geçtiği görüşünü reddetmesi', 'Çocukların dünyayı etkin biçimde keşfettiğini yadsıması'], 'Sonraki araştırmalar bebeklerin nesne sürekliliği gibi bazı anlayışları Piaget\'nin belirttiğinden daha erken gösterebildiğini ortaya koymuştur.'),
  ('Vygotsky\'nin \'yakınsal gelişim alanı\' kavramı neyi ifade eder?', 'Çocuğun tek başına yapabildiği ile yardımla yapabildiği arasındaki aralığı', ['Çocuğun doğuştan getirdiği refleksler bütününü', 'Çocuğun yaşadığı evin ve okulun fiziksel büyüklüğünü ve düzenini', 'Çocuğun yalnız başına çözemediği hiçbir şeyi öğrenemeyeceğini'], 'Vygotsky\'ye göre öğrenme en çok, çocuğun daha yetkin birinin desteğiyle başarabileceği görevlerde gerçekleşir.'),
  ('Orta yetişkinlikteki bir bireyin gönüllü olarak gençlere rehberlik etmesi ve gelecek kuşaklar için bir şeyler üretmeye çalışması Erikson\'a göre hangi kazanımdır?', 'Üretkenlik', ['Benlik bütünlüğü', 'Özerklik', 'Girişimcilik'], 'Orta yetişkinlikte birey, gelecek kuşaklara katkı sağlayarak üretkenlik duygusu kazanır; bunu başaramayan durgunluk yaşar.'),
  ('\'Arkadaşlarım ve öğretmenim beni iyi biri olarak görsün diye kopya vermiyorum\' diyen öğrencinin ahlaki gerekçesi Kohlberg\'e göre hangi evreye uygundur?', 'İyi çocuk (kişilerarası uyum) evresi', ['Ceza ve itaat evresi', 'Evrensel etik ilkeler evresi', 'Toplumsal sözleşme ve bireysel haklar evresi'], 'Geleneksel düzeyin ilk evresinde birey başkalarının onayını kazanmak ve \'iyi\' görünmek için kurallara uyar.'),
  ('Kohlberg\'in kuramına Carol Gilligan\'ın yönelttiği temel eleştiri nedir?', 'Kuramın erkek örneklemlere dayandığı ve \'bakım ahlakını\' ihmal ettiği', ['Kuramın ahlakı tümüyle biyolojik bir süreç sayması', 'Kuramın hiçbir ahlaki ikilem kullanmaması', 'Kuramın yalnızca bebekler üzerinde sınanmış olması'], 'Gilligan, Kohlberg\'in adalet odaklı ölçütlerinin ilişki ve özen temelli ahlaki yargıları daha düşük düzeyde göstermesine yol açtığını savunmuştur.'),
  ('Kohlberg kuramına göre aşağıdaki ifadelerden hangisi doğrudur?', 'Herkes en üst ahlak düzeyine ulaşamayabilir.', ['Herkes ergenlikte kesinlikle en üst düzeye ulaşır.', 'Evreler kişiden kişiye farklı sırayla yaşanır.', 'Ahlak gelişimi yalnızca ilk iki yılda tamamlanır.'], 'Kohlberg evrelerin değişmeyen bir sırayla ilerlediğini, ancak yetişkinlerin önemli bir kısmının gelenek sonrası düzeye ulaşmadığını belirtmiştir.'),
  ('Marcia\'ya göre ergenin farklı seçenekleri araştırmadan ailesinin ona çizdiği yolu ve değerleri sorgusuz benimsemesi hangi kimlik statüsüdür?', 'Kapanmış (ipotekli) kimlik', ['Başarılı (ulaşılmış) kimlik', 'Kimlik dağınıklığı', 'Askıya alınmış kimlik'], 'Kapanmış kimlikte kişi bir bağlılık geliştirmiştir ama bu bağlılık araştırma ve sorgulamadan sonra değil, başkalarının seçimlerini benimseyerek oluşmuştur.'),
  ('Hangi meslek ve dünya görüşünü seçeceğini aktif biçimde araştıran ancak henüz bir karara varmamış olan bir ergen Marcia\'ya göre hangi kimlik statüsündedir?', 'Askıya alınmış kimlik (moratoryum)', ['Kapanmış kimlik', 'Başarılı kimlik', 'Kimlik dağınıklığı (karmaşası)'], 'Moratoryumda kişi kimlik arayışını sürdürmektedir; seçenekleri araştırır ama henüz bağlanmamıştır.'),
  ('Maslow\'un kuramına yöneltilen eleştirilerden biri hangisidir?', 'İnsanların bazen alt ihtiyaçlar karşılanmadan üst ihtiyaçlara yönelebilmesi', ['Fizyolojik ihtiyaçları kuramın dışında bırakması', 'Kendini gerçekleştirme kavramına ve üst düzey ihtiyaçlara hiç yer vermemesi', 'Yalnızca hayvan deneylerine dayanması'], 'Örneğin bir sanatçı yoksulluk içinde eser üretebilir; bu da hiyerarşinin katı bir sıra izlemediğini düşündürür.'),
  ('Zevkle bulmaca çözen çocuklara her bulmaca için para verilmeye başlanıp sonra bu ödül kesildiğinde çocukların bulmaca çözme isteğinin azalması hangi olguyu gösterir?', 'Dışsal ödülün içsel güdülenmeyi zayıflatabilmesi', ['İçsel güdülenmenin parayla ödüllendirildiğinde her zaman güçlendiği', 'Ödülün kesilmesinin ilgiyi hep artırdığı', 'Bulmaca çözmenin biyolojik bir güdü olduğu'], 'Aşırı gerekçelendirme etkisi olarak bilinen bu olguda kişi davranışı ödüle bağlamaya başlar; ödül kalkınca içsel ilgi de azalır.'),
  ('Yerkes-Dodson yasasına göre performans ile uyarılma düzeyi arasındaki ilişki nasıldır?', 'Orta düzeyde uyarılma en iyi performansı sağlar.', ['Uyarılma arttıkça performans her zaman doğrusal olarak artar.', 'Uyarılmanın en düşük olduğu durumda performans en yüksektir.', 'Uyarılma ile performans arasında hiçbir ilişki bulunmaz.'], 'Ters U biçimindeki ilişkiye göre çok düşük ve çok yüksek uyarılma performansı düşürür; zor görevlerde en uygun düzey daha da düşüktür.'),
  ('Tok olduğu hâlde vitrinde gördüğü pastayı yemek isteyen kişinin davranışını en iyi açıklayan kuram hangisidir?', 'Özendirici (dış uyarıcı) kuramı', ['Dürtü azaltma kuramı', 'İçgüdü kuramı', 'Homeostazi (iç denge) kuramı'], 'Özendirici kuramına göre davranışı yalnız iç ihtiyaçlar değil, çekici dış uyarıcılar da harekete geçirir.'),
  ('Ağzında bir kalemi dişleriyle tutarak istemeden gülümseme kaslarını kasan katılımcıların karikatürleri daha komik bulması hangi görüşü destekler?', 'Yüz geri bildirimi hipotezini', ['İki etmen kuramını tümüyle çürüttüğünü', 'Duyguların yalnız bilişsel olduğunu', 'Cannon-Bard kuramının tek geçerli kuram olduğunu'], 'Yüz geri bildirimi hipotezine göre yüz kaslarının hareketi beyne geri bildirim vererek duygu yaşantısını etkileyebilir.'),
  ('Yaklaşma-kaçınma çatışmasında kişinin hedefe yaklaştıkça kararsızlığının ve kaygısının artmasının nedeni nedir?', 'Kaçınma eğiliminin yaklaşma eğiliminden daha hızlı artması', ['Yaklaşma eğiliminin hedefe yaklaşınca tümüyle yok olması', 'Hedefin olumsuz yönlerinin uzaktan bakıldığında daha belirgin ve güçlü görülmesi', 'Kişinin hedefi bütünüyle unutması ve ilgisini yitirmesi'], 'Lewin ve Miller\'ın çalışmalarına göre hedefe yaklaşıldıkça olumsuz yönlerin etkisi daha hızlı artar; bu nedenle kişi hedefin yakınında ileri geri gidip gelir.'),
  ('Rekabetçi, sabırsız, sürekli acele eden ve kolay öfkelenen kişilik örüntüsü hangisidir ve hangi sağlık sorunuyla ilişkilendirilmiştir?', 'A tipi kişilik; kalp ve damar hastalıkları', ['B tipi kişilik; kalp ve damar hastalıkları', 'A tipi kişilik; görme bozuklukları', 'B tipi kişilik; işitme kaybı ve kulak çınlaması'], 'Friedman ve Rosenman\'ın tanımladığı A tipi kişilikte özellikle düşmanca tutum bileşeninin kalp hastalıkları riskini artırdığı bulunmuştur.'),
  ('Holmes ve Rahe\'nin yaşam olayları ölçeğine göre aşağıdakilerden hangisi stres kaynağı olabilir?', 'Evlenmek gibi olumlu bir yaşam değişikliği', ['Yalnızca olumsuz yaşam değişiklikleri', 'Değişikliğin hiç yaşanmadığı sakin bir dönem', 'Yalnızca çocukken yaşanan olaylar'], 'Ölçek, uyum gerektiren her büyük değişikliğin, olumlu olsa bile, stres yaratabileceğini göstermiştir.'),
  ('Trafik sıkışıklığı, kayıp anahtarlar ve sıra beklemek gibi gündelik küçük sıkıntılara ne ad verilir ve sağlık açısından önemi nedir?', 'Gündelik sıkıntılar; birikerek önemli stres yaratabilirler', ['Gündelik sıkıntılar; sağlık üzerinde hiçbir etkileri yoktur', 'Travmatik olaylar; tek seferde ağır hasar bırakırlar', 'Yaşam krizleri; yalnızca yaşlılıkta görülürler'], 'Araştırmalar, küçük ama sık yaşanan sıkıntıların birikerek büyük yaşam olayları kadar sağlığı etkileyebildiğini göstermiştir.'),
  ('Bastırma ile bilinçli olarak bir düşünceyi aklından uzaklaştırmaya çalışma arasındaki temel fark nedir?', 'Bastırma bilinçdışı, diğeri bilinçli bir süreçtir.', ['Bastırma bilinçli ve istemli, diğeri ise tümüyle bilinçdışıdır.', 'İkisi de aynı süreçtir ve aralarında hiçbir fark yoktur.', 'Bastırma yalnızca çocuklukta, diğeri yalnızca yaşlılıkta görülür.'], 'Bastırmada acı veren anılar kişinin farkında olmadan bilinçdışına itilir; bilinçli olarak düşünmemeye çalışmak ise baskılama olarak adlandırılır.'),
  ('Çok acıkmış bir öğrenci kantinden izinsiz bir sandviç almayı düşünüyor, ama \'Bu hırsızlık olur\' diye kendini durduruyor ve parasını bulup sandviçi satın alıyor. Bu süreçte \'Bu hırsızlık olur\' düşüncesi ile sandviçi satın alma kararı sırasıyla hangi yapılara aittir?', 'Süperego ve ego', ['İd ve süperego', 'Ego ve id', 'Süperego ve id'], 'Ahlaki yasağı süperego dile getirir; açlığı gerçekçi ve kabul edilebilir bir yolla gidermenin yolunu bulan ise egodur.'),
  ('Allport\'un özellik sınıflandırmasında bir kişinin neredeyse tüm davranışlarına damgasını vuran baskın özelliğe ne ad verilir?', 'Temel (kardinal) özellik', ['İkincil özellik', 'Merkezî özellik', 'Durumsal ve geçici özellik'], 'Allport\'a göre temel özellik kişinin yaşamını bütünüyle yönlendiren tek ve baskın özelliktir; çoğu insanda bulunmaz.'),
  ('Bir yıldız falı okuyan kişinin \'Bazen dışa dönük, bazen içine kapanıksınız\' gibi herkese uyabilecek genel ifadeleri kendisine özgü sanmasına ne ad verilir?', 'Barnum (Forer) etkisi', ['Hawthorne etkisi', 'Plasebo (beklenti) etkisi', 'Hale etkisi'], 'Belirsiz ve genel kişilik betimlemelerinin kişiye özgü ve doğru algılanması Barnum etkisi olarak bilinir.'),
  ('Kişilik özelliklerinin farklı durumlarda ne ölçüde tutarlı olduğu tartışmasında Mischel\'in vurguladığı görüş hangisidir?', 'Davranışın büyük ölçüde durumun özelliklerine göre değişebildiği', ['Kişiliğin her durumda tam olarak aynı davranışı ürettiği', 'Kişiliğin yalnızca kalıtım tarafından belirlendiği ve hiç değişmediği', 'Durumların davranış üzerinde hiçbir etkisinin olmadığı'], 'Mischel, aynı kişinin farklı durumlarda farklı davranabildiğini göstererek kişi-durum etkileşimine dikkat çekmiştir.'),
  ('\'Ne kadar çalışsam da not öğretmenin keyfine bağlı\' diye düşünen bir öğrencinin denetim odağı hangisidir ve bunun olası sonucu nedir?', 'Dış denetim odağı; çaba göstermeye isteksizlik', ['İç denetim odağı; çalışmaya daha fazla güdülenme', 'İç denetim odağı; sınav kaygısının tümüyle kaybolması', 'Dış denetim odağı; kendine aşırı güven duyma'], 'Sonucun kendi elinde olmadığını düşünen kişi çaba göstermenin anlamsız olduğuna inanabilir.'),
  ('Şizofrenideki \'sanrı\' ile \'varsanı\' arasındaki fark nedir?', 'Sanrı yanlış ve sarsılmaz bir inanç, varsanı ise uyarıcı olmadan oluşan algıdır.', ['İkisi de aynı belirtiyi anlatır ve aralarında fark bulunmaz.', 'Sanrı uyarıcı olmadan duyulan sesler, varsanı ise mantıklı ve kanıta dayalı bir inançtır.', 'Sanrı yalnız görme, varsanı ise yalnız koku ile ilgilidir.'], 'Örneğin izlendiğine kesin inanmak sanrı, ortada kimse yokken ses duymak ise varsanıdır (halüsinasyon).'),
  ('Halk arasında şizofreninin \'çoklu kişilik\' anlamına geldiği sanılır. Bu düşünce neden yanlıştır?', 'Çoklu kişilik ayrı bir bozukluk olup şizofreni gerçeklikle bağın kopmasıdır.', ['Şizofreni yalnızca çocuklarda ve gençlerde görülen, okul başarısını düşüren bir öğrenme güçlüğüdür.', 'Çoklu kişilik diye bir kavram psikolojide hiç tanımlanmamıştır.', 'Şizofreni kaygı bozukluklarının en hafif ve geçici biçimidir.'], 'Çoklu kişilik bugün dissosiyatif kimlik bozukluğu olarak ayrı sınıflanır; şizofrenideki \'bölünme\' düşünce ile duygu ve gerçeklik arasındadır.'),
  ('Kendisine mesajına geç yanıt veren arkadaşının kesinlikle ona kızgın olduğunu düşünen bir kişinin düşünce hatası hangisidir?', 'Zihin okuma', ['Aşırı genelleme', 'Felaketleştirme', 'Etiketleme'], 'Zihin okumada kişi yeterli kanıt olmadan başkalarının kendisi hakkında olumsuz düşündüğüne karar verir.'),
  ('Psikanalitik terapide danışanın çocukluktaki önemli kişilere yönelik duygularını terapiste yöneltmesine ne ad verilir?', 'Aktarım', ['Direnç', 'Yüceltme', 'Ket vurma'], 'Aktarım psikanalitik terapinin temel kavramlarındandır; terapist bu duyguları çözümleyerek danışanın bilinçdışı çatışmalarına ulaşır.'),
  ('Bilişsel-davranışçı terapinin günümüzde yaygın kullanılmasının en önemli nedeni hangisidir?', 'Birçok bozuklukta etkililiğinin bilimsel araştırmalarla desteklenmesi', ['Terapistin hiçbir eğitim almasına ve denetim altında çalışmasına gerek olmaması', 'Tedavinin her zaman tek bir oturumda tamamlanması', 'Danışanın düşüncelerinin hiç ele alınmaması'], 'Bilişsel-davranışçı terapinin kaygı bozuklukları ve depresyon gibi birçok sorunda etkili olduğu kontrollü çalışmalarla gösterilmiştir.'),
  ('Milgram deneyinin çeşitlemelerinde itaat oranını düşürdüğü bulunan durumlardan biri hangisidir?', 'Deney yöneticisinin talimatlarını telefonla, odada bulunmadan vermesi', ['Deney yöneticisinin önlük giyerek odada bulunması', 'Deneyin ünlü ve saygın bir üniversitenin laboratuvarında yapılması', 'Öğrencinin başka bir odada bulunup görülmemesi'], 'Yetke figürünün fiziksel olarak uzaklaşması, kurbanın yakınlaşması ve itaat etmeyen bir model görülmesi itaati azaltan etkenlerdir.'),
  ('Bir çalışanın patronuna yakın görünmek için toplantıda inanmadığı bir fikri onaylaması, ancak içten içe fikrini değiştirmemesi hangi uyma türüdür?', 'Boyun eğme (dışsal uyma)', ['İçselleştirme (inançların değişmesi)', 'Özdeşleşme', 'Bilişsel çelişki'], 'Boyun eğmede kişi ödül kazanmak ya da cezadan kaçmak için dışarıdan uyar; ancak inançları değişmez.'),
  ('Bilişsel çelişki yaşayan bir sigara tiryakisinin \'Dedem de içiyordu, doksan yaşına kadar yaşadı\' demesi çelişkiyi azaltmanın hangi yoluna örnektir?', 'Çelişkiyi azaltacak yeni bir biliş eklemek', ['Davranışı tümüyle değiştirmek', 'Çelişkiyi açıkça kabul edip artırmak', 'Bilişsel çelişkiyi hiç yaşamadığını ve rahat olduğunu söylemek'], 'Kişi davranışını değiştirmek yerine davranışını haklı gösteren yeni düşünceler ekleyerek çelişkiyi hafifletir.'),
  ('Festinger ve Carlsmith\'in deneyinde sıkıcı bir görevi başkasına \'eğlenceli\' diye anlatmaları için 1 dolar alan katılımcılar, 20 dolar alanlara göre görevi sonradan nasıl değerlendirmiştir?', 'Daha eğlenceli', ['Daha sıkıcı', 'Tam olarak aynı', 'Hiç değerlendirmemiştir'], 'Az ödül alanlar yalanlarını parayla gerekçelendiremedikleri için çelişkiyi tutumlarını değiştirerek, yani görevi daha eğlenceli bularak azaltmıştır.'),
  ('\'Onların hepsi birbirine benzer, ama bizim grubumuzda herkes farklıdır\' düşüncesi hangi olguyu yansıtır?', 'Dış grup türdeşliği etkisi', ['İç grup kayırmacılığı etkisi', 'Kendine hizmet eden yanlılık', 'Sosyal kolaylaştırma'], 'İnsanlar dış grup üyelerini birbirine daha benzer, kendi grup üyelerini ise daha çeşitli algılama eğilimindedir.'),
  ('Önyargıyı azaltmada temas hipotezine göre gruplar arası temasın etkili olması için hangi koşul önemlidir?', 'Eşit statüde ve ortak hedefler doğrultusunda işbirliği', ['Grupların yalnızca rekabet içinde karşılaşması', 'Bir grubun diğerine üstün konumda bulunması', 'Temasın çok kısa, yüzeysel ve zorunlu biçimde tutulması'], 'Allport\'un temas hipotezine göre eşit statü, ortak amaç, işbirliği ve kurumsal destek koşullarında temas önyargıyı azaltır.'),
  ('Benzer görüşteki kişilerden oluşan bir grubun tartışma sonrasında başlangıçtaki eğilimini daha da uç bir noktaya taşımasına ne ad verilir?', 'Grup kutuplaşması', ['Sosyal kaytarma', 'Grup içi kayırmacılık', 'Kendine hizmet eden yanlılık'], 'Grup tartışmaları üyelerin var olan görüşlerini güçlendirerek daha uç kararlara yol açabilir.'),
  ('Kalabalık içinde kimliğinin fark edilmeyeceğini düşünen kişilerin tek başınayken yapmayacakları davranışlara girişmesine ne ad verilir?', 'Bireysizleşme', ['Sosyal kolaylaştırma', 'İçselleştirme', 'Bilişsel çelişki ve tutum değişimi'], 'Bireysizleşmede kişi öz farkındalığını ve kişisel sorumluluk duygusunu yitirerek grubun davranışına kapılır.'),
  ('Hipnoz hakkında aşağıdaki ifadelerden hangisi bilimsel bulgularla en uyumludur?', 'Hipnozda kişinin telkinlere açıklığı artar, ancak kişiler buna yatkınlık bakımından farklılık gösterir.', ['Hipnoz kişiyi her türlü iradesini yitirmiş bir uykuya sokar.', 'Hipnoz altında hatırlanan her anı kesinlikle doğrudur.', 'Herkes hipnoza tam olarak aynı ölçüde yatkındır.'], 'Hipnoz bir tür odaklanmış dikkat ve artmış telkine açıklık durumudur; hipnozla canlandırılan anılar ise yanlış bilgi içerebilir.'),
  ('Bir kişi bir hareketi yaparken de aynı hareketi başkasında izlerken de etkinleşen sinir hücrelerine ne ad verilir?', 'Ayna nöronlar', ['Motor nöronlar ve kas lifleri', 'Duyu nöronları', 'Glia hücreleri'], 'Ayna nöronların taklit, öğrenme ve başkalarının eylemlerini anlamada rol oynadığı düşünülmektedir.'),
  ('Thomas ve Chess\'in mizaç araştırmalarına göre düzenli uyku-beslenme ritmi olan, yeni durumlara kolay uyum sağlayan ve genellikle neşeli bebek hangi mizaç grubundadır?', 'Kolay mizaçlı', ['Zor mizaçlı', 'Geç ısınan mizaçlı', 'Kaçıngan mizaçlı'], 'Bebeklerin büyük kısmı kolay mizaç grubundadır; zor mizaçlılar düzensiz ve yoğun tepkili, geç ısınanlar ise yeniliğe yavaş uyum sağlayan bebeklerdir.'),
  ('Maslow\'un kendini gerçekleştirmiş kişilerde gözlediği, kişinin kendini aşarak derin bir mutluluk ve bütünlük duygusu yaşadığı anlara ne ad verilir?', 'Doruk deneyimler', ['Kavrayış anları', 'Serbest çağrışımlar', 'Bastırılmış çocukluk anıları'], 'Maslow\'a göre doruk deneyimler, kendini gerçekleştirmiş bireylerde daha sık görülen yoğun anlam ve coşku anlarıdır.'),
  ('Benlik kavramı ile benlik saygısı arasındaki fark en doğru hangi seçenekte verilmiştir?', 'Benlik kavramı kişinin kendini nasıl tanımladığı, benlik saygısı ise kendine ne kadar değer verdiğidir.', ['Benlik kavramı yalnızca bedensel özellikleri, benlik saygısı yalnızca zekâyı kapsar.', 'İkisi tam olarak aynı anlama gelir ve birbirinin yerine kullanılır.', 'Benlik saygısı doğuştan sabittir, benlik kavramı ise yalnızca yaşlılıkta oluşur.'], 'Benlik kavramı \'Ben kimim?\' sorusunun bilişsel yanıtıdır; benlik saygısı ise bu benliğe yönelik olumlu ya da olumsuz değerlendirmedir.'),
  ('Dilimizdeki tat almaçlarının tanıdığı temel tatlara, tatlı, ekşi, tuzlu ve acıya ek olarak sonradan eklenen beşinci tat hangisidir?', 'Umami', ['Baharatlı', 'Metalik', 'Serinletici'], 'Umami, özellikle et suyu ve bazı peynirlerde bulunan glutamatın verdiği tattır ve beşinci temel tat olarak kabul edilir.'),
  ('Yeni doğan bebeklerin görme duyusu hakkında hangisi doğrudur?', 'Görme keskinliği düşüktür ve en iyi yaklaşık 20-30 cm uzaklıktaki yüzleri görürler.', ['Doğar doğmaz yetişkinler kadar keskin ve ayrıntılı görürler.', 'İlk bir yıl boyunca hiçbir şey göremezler.', 'Yalnızca çok uzaktaki nesneleri ve ufuk çizgisini net biçimde görebilirler.'], 'Yenidoğanların görmesi bulanıktır; yaklaşık kucaktaki bebeğin anne yüzüne uzaklığı kadar mesafede en iyi görürler ve yüzlere özel ilgi gösterirler.'),
  ('İstenmeyen bir davranışı azaltmak için ceza yerine, o davranışla bir arada yapılamayacak olumlu bir davranışı pekiştirmeye ne ad verilir?', 'Uyumsuz (karşıt) davranışın pekiştirilmesi', ['Olumsuz pekiştirme ve kaçma yoluyla öğrenme', 'Kendiliğinden geri gelme', 'Uyarıcı genellemesi'], 'Örneğin sınıfta koşan çocuğun yerinde oturduğu anlar övülür; oturmak ile koşmak aynı anda yapılamayacağı için istenmeyen davranış azalır.'),
];
